// W3C Data Integrity proof for a VerifiablePresentation. Extends the base
// DataIntegrityProof with challenge and domain per W3C VC Data Model 5.6.
// proofPurpose is constrained to 'authentication': the holder is authenticating
// themselves as the presenter of the enclosed credentials.
type VPDataIntegrityProof struct {
	// Replay-binding challenge. The verifier requires this to equal request_hash —
	// the content hash of the inner PaymentRequest — recomputed from the received
	// request; mismatch indicates either a stale PRE from a different request or a
	// forged envelope. request_hash includes request_id (the idempotency key) so
	// distinct requests get distinct challenges; binding to the content hash rather
	// than payment_id re-anchors replay protection to a real protocol-level identity.
	Challenge string `json:"challenge" yaml:"challenge" mapstructure:"challenge"`

	// ISO 8601 timestamp when the proof was created. Canonicalize the value exactly
	// as it appears in the raw JSON: parsing it into a date-time and re-serializing
	// can change the spelling (Z versus +00:00), and a different spelling
	// canonicalizes to different bytes, so the signature no longer verifies. The
	// verifier also checks freshness against its configured maximum proof age and
	// future-skew window.
	Created time.Time `json:"created" yaml:"created" mapstructure:"created"`

	// Replay-binding domain. The verifier requires this to equal its configured
	// service identifier — locked to a NETWORK-WIDE value
	// `did:web:<env>.atum.network` (e.g., `did:web:atum.network`). Distinct from
	// FQE's `did:web:settler.<env>.atum.network` so a captured PRE can't be misrouted
	// to FQE-shaped verifiers. Without this, a captured PRE from one environment
	// could be replayed against another by the same originator.
	Domain string `json:"domain" yaml:"domain" mapstructure:"domain"`

	// Detached JWS signature in <base64url(header)>..<base64url(sig)> form, header
	// {alg:ES256K-R, b64:false, crit:[b64]}. Used by the
	// EcdsaSecp256k1RecoverySignature2020 cryptosuite. Exactly one of jws /
	// proofValue must be present, matching the cryptosuite.
	Jws *string `json:"jws,omitempty" yaml:"jws,omitempty" mapstructure:"jws,omitempty"`

	// Always 'authentication' for VerifiablePresentation proofs per W3C VC Data Model
	// §5.6 — the holder is authenticating themselves as the presenter of the enclosed
	// credentials.
	ProofPurpose string `json:"proofPurpose" yaml:"proofPurpose" mapstructure:"proofPurpose"`

	// Multibase z-base58btc-encoded 64-byte signature. Used by the
	// Ed25519Signature2020 cryptosuite. Exactly one of jws / proofValue must be
	// present, matching the cryptosuite.
	ProofValue *string `json:"proofValue,omitempty" yaml:"proofValue,omitempty" mapstructure:"proofValue,omitempty"`

	// Proof type identifier. MUST be one of EcdsaSecp256k1RecoverySignature2020
	// (secp256k1) or Ed25519Signature2020 (ed25519), and MUST equal the inner
	// declaration's proof.type so the holder-binding consistency check anchors both
	// signatures to the same cryptosuite.
	Type string `json:"type" yaml:"type" mapstructure:"type"`

	// DID URL identifying the verification method, e.g.,
	// 'did:pkh:eip155:1:0x...#blockchainAccountId' for ECDSA or
	// 'did:pkh:solana:<chain>:<addr>#SolanaMethod2021' for Ed25519 on Solana, or
	// 'did:pkh:stellar:<network>:<G-account>#blockchainAccountId' for Ed25519 on
	// Stellar. The recovered identity from this MUST match the holder field.
	VerificationMethod string `json:"verificationMethod" yaml:"verificationMethod" mapstructure:"verificationMethod"`
}

